/* =====================================================
   gate.js : the way into the review is guarded (product page). window.gate.start(onPass)
   "I'm not a robot" boxes are spammed all over the screen. A few of them say something else ("I'm not real", "I'm not authentic" ...).
   Only when EVERY "I'm not a robot" box is ticked is Maya satisfied. Ticking one of the others is the wrong answer: she says so,
   the box crosses itself out, and ANOTHER robot box is added. The third wrong answer ends it: she refuses, the boxes go, and the button has to be pressed again.
   Wrong answers are counted per round: the second time the wording is harder, and three wrong then means the red eye and the agreement.
   Once passed it is remembered for this visit (sessionStorage 'realStuf.gate'), and review.html will not open without it.
   Needs: css/gate.css and css/checks.css (the box look), js/assistant.js (Maya speaks; the gate still works without her).
   ===================================================== */
(function () {
  /* ---------- the wording and the knobs ---------- */
  // the rounds: the first time, then (after being turned away) the second time, which is harder.
  //   good = the boxes that count | bad = the ones that are the truth (ticking one counts against you) | start = Maya as they appear
  //   onFail 'cams' = three wrong, she gets suspicious, two cameras open and the next round starts by itself | 'refuse' = three wrong and she turns them away | 'eye' = three wrong and the red eye warning, then the agreement, then she lets them in
  const ROUNDS = [
    { good: ['This shirt is 100% real', 'This shirt is genuine', 'This shirt is original', 'This site is real', 'This shirt is not fake'],
      bad: ['This shirt is almost real', 'This shirt is probably genuine', 'This site is not not fake', 'This shirt is not entirely original', 'This shirt is not not fake'],
      start: ['first, i need to make sure you know what to say', 'tick every box that speaks the truth.', 'then...ill let you through'], onFail: 'cams' },
    { good: ['this site is authentic', 'this shirt is authentic', 'this site is genuine', 'this shirt is the real thing', 'this site is 100% real'],
      bad: ['i can say what i want', 'I have my own opinions', 'i will review this shirt however I choose'],
      start: ['read them properly this time.'], onFail: 'eye', cams: true }
  ];
  const BOXES_AFTER = 300;                                          // ms between Maya finishing her lines and the first box appearing
  const OTHERS_EACH = 1;                                            // how many copies of each of those
  const SPREAD_MS = 320;                                            // ms between one box appearing and the next
  const SPIN_MS = 900;                                              // how long a box "checks" before it ticks
  const WRONG = [['...no.', 'that is not what we asked.'], ['...be careful.', 'tick the right ones.']];    // Maya, when they tick a true one
  const MAX_WRONG = 3;                                              // this many true boxes ticked and she does not let them through: they have to press the button again
  const FAILED = ['...no.', 'that is three.', 'you are not coming in. press the button again if you want to try.'];     // Maya, when they run out of chances
  const FAIL_AFTER = 4200;                                          // ms for her to say it before the boxes go
  const SUSPICIOUS = ['hmm... now why would you answer those wrong...'];                                              // Maya, when they fail the first round
  const TRY_AGAIN = ['try again.', 'do not get it wrong this time.'];                                               // Maya, then the second round starts by itself
  const CAMS_AT = 1800, TRY_AT = 4800, AGAIN_AT = 9000;                                                              // ms after the third wrong: the two cameras, her next lines, the new boxes
  const EYE_SIGN_ASK = ['...you keep getting it wrong.', 'sign the agreement. then I will trust you.'];                 // Maya, after the red eye: the agreement opens (js/certs.js)
  const EYE_SIGNED = ['...fine.', 'with your signature, I trust you enough to let you make a review.', 'go on.'];  // Maya, once it is signed: in they go
  const PASSED = ['fine...', 'you seem real enough to only state the truth.'];                  // Maya, when every robot box is ticked
  const PASS_AFTER = 3200;                                          // ms after the last tick before onPass runs (time for her to speak)

  const KEY = 'realStuf.gate';
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const say = function (lines) { window.maya && maya.say(lines, null, true); };
  const pick = function (a) { return a[Math.floor(Math.random() * a.length)]; };
  const passed = function () { try { return sessionStorage.getItem(KEY) === '1'; } catch (e) { return false; } };

  let R = ROUNDS[0], layer = null, running = false, left = 0, spots = [], wrongN = 0, run = 0;

  // places on the screen: a loose grid, shuffled, each spot jittered, so the boxes are all over without piling up
  function makeSpots() {
    const cols = innerWidth < 600 ? 2 : 4, rows = innerWidth < 600 ? 6 : 3, top = 70, bottom = 70;
    const cw = innerWidth / cols, ch = (innerHeight - top - bottom) / rows, out = [];
    for (let c = 0; c < cols; c++) for (let r = 0; r < rows; r++) out.push({ x: c * cw, y: top + r * ch, w: cw, h: ch });
    return out.sort(function () { return Math.random() - .5; });
  }
  function nextSpot() { if (!spots.length) spots = makeSpots(); return spots.pop(); }

  function card(label, isRobot) {
    const s = nextSpot(), el = document.createElement('div');
    el.className = 'gt-card'; el.dataset.robot = isRobot ? '1' : '0';
    el.innerHTML = '<div class="cap-row"><button class="cap-box" type="button" role="checkbox" aria-checked="false"></button><span></span></div><div class="cap-foot">Real Stuf. verification</div>';
    el.querySelector('span').textContent = label; el.querySelector('.cap-box').setAttribute('aria-label', label);
    const W = Math.min(236, innerWidth / 2 - 12);
    el.style.left = Math.max(6, Math.min(innerWidth - W - 6, s.x + Math.random() * Math.max(0, s.w - W))) + 'px';
    el.style.top = Math.max(60, Math.min(innerHeight - 100, s.y + Math.random() * Math.max(0, s.h - 76))) + 'px';
    el.querySelector('.cap-box').addEventListener('click', function () { tick(el, isRobot); });
    layer.appendChild(el); window.sfx && sfx('slip');
    return el;
  }

  function tick(el, isRobot) {
    const mine = run;
    const box = el.querySelector('.cap-box');
    if (box.classList.contains('spin') || box.classList.contains('ok') || box.classList.contains('no')) return;
    window.sfx && sfx('click'); box.classList.add('spin');
    setTimeout(function () {
      if (mine !== run || !layer) return;                          // the gate has already ended
      box.classList.remove('spin');
      if (isRobot) {
        box.classList.add('ok'); box.setAttribute('aria-checked', 'true'); window.sfx && sfx('done');
        if (--left <= 0) win();
      } else {                                                     // the truth is the wrong answer
        box.classList.add('no'); el.classList.add('shake'); window.sfx && sfx('warn', 1);
        if (++wrongN >= MAX_WRONG) { fail(); return; }
        say(WRONG[(wrongN - 1) % WRONG.length]); left++; setTimeout(function () { if (mine === run && layer) card(pick(R.good), true); }, 700);
        setTimeout(function () { el.classList.add('out'); setTimeout(function () { el.remove(); }, 400); }, 1200);
      }
    }, reduce ? 0 : SPIN_MS);
  }

  function clear(then) {                                           // the boxes go
    if (!layer) return;
    layer.querySelectorAll('.gt-card').forEach(function (c) { c.classList.add('out'); });
    layer.classList.remove('on');
    setTimeout(function () { if (layer) layer.remove(); layer = null; running = false; then && then(); }, 700);
  }
  let holdEl = null;                                              // an invisible blocker for the gap between round one and round two, so the page cannot be clicked then either
  function hold() { if (holdEl) return; holdEl = document.createElement('div'); holdEl.style.cssText = 'position:fixed;inset:0;z-index:52;pointer-events:auto'; ['wheel', 'touchmove'].forEach(function (ev) { holdEl.addEventListener(ev, function (e) { e.preventDefault(); }, { passive: false }); }); document.body.appendChild(holdEl); }
  function release() { if (holdEl) { holdEl.remove(); holdEl = null; } }
  function fail() {                                                // three wrong
    ++run;
    if (R.onFail === 'eye' && window.certs && certs.gateSign) {     // second time: the red eye, then the agreement, then she lets them in
      clear(function () { certs.gateSign(function () { try { sessionStorage.setItem(KEY, '1'); } catch (e) {} window.certs && certs.camsOff && certs.camsOff(); if (done) done(); }, EYE_SIGN_ASK, EYE_SIGNED); });
      return;
    }
    try { sessionStorage.setItem('realStuf.gateFails', String(Number(sessionStorage.getItem('realStuf.gateFails') || 0) + 1)); } catch (e) {}
    if (R.onFail === 'cams') {                                       // first time: she gets suspicious, two cameras open, and the second round starts by itself
      const cb = done;
      say(SUSPICIOUS); hold(); clear();
      setTimeout(function () { window.certs && certs.cams && certs.cams(2); }, CAMS_AT);
      setTimeout(function () { say(TRY_AGAIN); }, TRY_AT);
      setTimeout(function () { start(cb); }, AGAIN_AT);
      return;
    }
    say(FAILED);
    setTimeout(function () { clear(); }, FAIL_AFTER);
  }

  function win() {
    try { sessionStorage.setItem(KEY, '1'); } catch (e) {}
    say(PASSED);
    setTimeout(function () {
      layer.querySelectorAll('.gt-card').forEach(function (c) { c.classList.add('out'); });
      layer.classList.remove('on');
      setTimeout(function () { layer.remove(); layer = null; running = false; window.certs && certs.camsOff && certs.camsOff(); if (done) done(); }, 700);
    }, PASS_AFTER);
  }

  let done = null;
  function start(onPass) {
    if (passed()) { onPass && onPass(); return; }
    if (running) return;
    const fails = Number(sessionStorage.getItem('realStuf.gateFails') || 0); R = ROUNDS[Math.min(fails, ROUNDS.length - 1)];
    running = true; done = onPass; left = R.good.length; spots = []; wrongN = 0; const mine = ++run;
    layer = document.createElement('div'); layer.className = 'gt-layer'; document.body.appendChild(layer);
    release();
    layer.style.pointerEvents = 'auto';                                // blocks every click on the page behind, whatever gate.css says
    ['wheel', 'touchmove'].forEach(function (ev) { layer.addEventListener(ev, function (e) { e.preventDefault(); }, { passive: false }); });      // the page behind cannot be scrolled while the boxes are up
    const prep = document.querySelectorAll('[data-prep]');             // the screen is already dark (js/review-game.js darkened it when Make a Review was pressed): this layer starts at the same darkness and the first one goes in the same frame, so nothing flashes
    if (prep.length) {
      layer.style.transition = 'none'; layer.classList.add('on'); prep.forEach(function (v) { v.remove(); });
      requestAnimationFrame(function () { requestAnimationFrame(function () { if (layer) layer.style.transition = ''; }); });
    } else requestAnimationFrame(function () { layer.classList.add('on'); });
    if (R.cams && window.certs && certs.cams) certs.cams(2);          // the cameras from the first failure stay up
    const list = [];                                              // all the boxes, shuffled
    R.good.forEach(function (t) { list.push([t, true]); });
    R.bad.forEach(function (t) { for (let k = 0; k < OTHERS_EACH; k++) list.push([t, false]); });
    list.sort(function () { return Math.random() - .5; });
    // the boxes only start to appear once Maya has finished saying her lines ("...prove it first." / "tick every box that says the truth.")
    const spawn = function () { list.forEach(function (c, i) { setTimeout(function () { if (layer && mine === run) card(c[0], c[1]); }, BOXES_AFTER + i * SPREAD_MS); }); };
    if (window.maya && maya.say) maya.say(R.start, function () { if (layer && mine === run) spawn(); }, true); else spawn();
  }

  window.gate = { start: start, passed: passed };
})();
